package com.travelsync.data;

import com.travelsync.model.*;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;

import java.time.LocalDateTime;

/**
 * Central in-memory data store for the running application. Holds observable
 * lists so the UI updates live when bookings/notifications change, and owns
 * the notification feed generated by real application events.
 */
public final class AppDataStore {

    private static final AppDataStore INSTANCE = new AppDataStore();
    public static AppDataStore getInstance() { return INSTANCE; }

    private final ObservableList<Destination> destinations;
    private final ObservableList<Attraction> attractions;
    private final ObservableList<Hotel> hotels;
    private final ObservableList<Transportation> transportation;
    private final ObservableList<Traveler> travelers;
    private final ObservableList<Booking> bookings;
    private final ObservableList<TravelService> services;
    private final ObservableList<TravelDocument> documents;
    private final ObservableList<AppNotification> notifications;

    private AppDataStore() {
        destinations = FXCollections.observableArrayList(SampleDataGenerator.generateDestinations());
        attractions = FXCollections.observableArrayList(SampleDataGenerator.generateAttractions());
        hotels = FXCollections.observableArrayList(SampleDataGenerator.generateHotels());
        transportation = FXCollections.observableArrayList(SampleDataGenerator.generateTransportation());
        travelers = FXCollections.observableArrayList(SampleDataGenerator.generateTravelers());
        bookings = FXCollections.observableArrayList(
                SampleDataGenerator.generateBookings(travelers, destinations, hotels, transportation));
        services = FXCollections.observableArrayList(SampleDataGenerator.generateServices());
        documents = FXCollections.observableArrayList(SampleDataGenerator.generateDocuments(travelers, bookings));
        notifications = FXCollections.observableArrayList();

        notifications.add(new AppNotification("Welcome to TravelSync",
                "Demo data loaded: " + destinations.size() + " destinations, " + bookings.size() + " bookings.",
                LocalDateTime.now()));
    }

    public void pushNotification(String title, String message) {
        notifications.add(0, new AppNotification(title, message, LocalDateTime.now()));
    }

    /** Regenerates all demo data in place (used by the real "Reset demo data" Settings action). */
    public void resetDemoData() {
        destinations.setAll(SampleDataGenerator.generateDestinations());
        attractions.setAll(SampleDataGenerator.generateAttractions());
        hotels.setAll(SampleDataGenerator.generateHotels());
        transportation.setAll(SampleDataGenerator.generateTransportation());
        travelers.setAll(SampleDataGenerator.generateTravelers());
        bookings.setAll(SampleDataGenerator.generateBookings(travelers, destinations, hotels, transportation));
        services.setAll(SampleDataGenerator.generateServices());
        documents.setAll(SampleDataGenerator.generateDocuments(travelers, bookings));
        pushNotification("Demo data reset", "All sample data has been regenerated.");
    }

    public ObservableList<Destination> getDestinations() { return destinations; }
    public ObservableList<Attraction> getAttractions() { return attractions; }
    public ObservableList<Hotel> getHotels() { return hotels; }
    public ObservableList<Transportation> getTransportation() { return transportation; }
    public ObservableList<Traveler> getTravelers() { return travelers; }
    public ObservableList<Booking> getBookings() { return bookings; }
    public ObservableList<TravelService> getServices() { return services; }
    public ObservableList<TravelDocument> getDocuments() { return documents; }
    public ObservableList<AppNotification> getNotifications() { return notifications; }

    public Destination findDestination(String id) {
        return destinations.stream().filter(d -> d.getId().equals(id)).findFirst().orElse(null);
    }
}
